CREATE TABLE IF NOT EXISTS sd_service_catalog(id TEXT PRIMARY KEY,reference TEXT NOT NULL UNIQUE COLLATE NOCASE,country_code TEXT NOT NULL,name TEXT NOT NULL,category TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','published','retired')),customer_visible INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_by TEXT REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_business_calendars(id TEXT PRIMARY KEY,country_code TEXT NOT NULL,name TEXT NOT NULL,timezone TEXT NOT NULL,data TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_contract_policies(id TEXT PRIMARY KEY,country_code TEXT NOT NULL,service_id TEXT REFERENCES sd_service_catalog(id),contract_id TEXT REFERENCES managed_contracts(id),sla_entry_id TEXT REFERENCES contract_entries(id),priority TEXT NOT NULL CHECK(priority IN ('low','medium','high','critical')),state TEXT NOT NULL DEFAULT 'draft' CHECK(state IN ('draft','active','retired')),calendar_id TEXT REFERENCES sd_business_calendars(id),response_minutes INTEGER NOT NULL CHECK(response_minutes>0),resolution_minutes INTEGER NOT NULL CHECK(resolution_minutes>=response_minutes),pause_on_hold INTEGER NOT NULL DEFAULT 0,data TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,updated_by TEXT REFERENCES users(id),updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS sd_policy_scope ON sd_contract_policies(country_code,IFNULL(service_id,''),IFNULL(contract_id,''),IFNULL(sla_entry_id,''),priority);
CREATE TABLE IF NOT EXISTS sd_catalog_audit(id TEXT PRIMARY KEY,country_code TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,actor_id TEXT REFERENCES users(id),action TEXT NOT NULL,snapshot TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sd_catalog_guards(entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,revision INTEGER NOT NULL,PRIMARY KEY(entity_type,entity_id));
CREATE TRIGGER IF NOT EXISTS sd_catalog_revision BEFORE INSERT ON sd_catalog_guards WHEN (NEW.entity_type='service' AND NOT EXISTS(SELECT 1 FROM sd_service_catalog WHERE id=NEW.entity_id AND revision=NEW.revision)) OR (NEW.entity_type='calendar' AND NOT EXISTS(SELECT 1 FROM sd_business_calendars WHERE id=NEW.entity_id AND revision=NEW.revision)) OR (NEW.entity_type='policy' AND NOT EXISTS(SELECT 1 FROM sd_contract_policies WHERE id=NEW.entity_id AND revision=NEW.revision)) BEGIN SELECT RAISE(ABORT,'Catalog revision conflict'); END;
CREATE INDEX IF NOT EXISTS sd_catalog_country ON sd_service_catalog(country_code,state,customer_visible);
CREATE INDEX IF NOT EXISTS sd_contract_policy_country ON sd_contract_policies(country_code,state,priority);
CREATE TRIGGER IF NOT EXISTS sd_active_policy_insert_guard BEFORE INSERT ON sd_contract_policies WHEN NEW.state='active' AND ((NEW.calendar_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sd_business_calendars WHERE id=NEW.calendar_id AND country_code=NEW.country_code AND active=1)) OR (NEW.service_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sd_service_catalog WHERE id=NEW.service_id AND country_code=NEW.country_code AND state='published'))) BEGIN SELECT RAISE(ABORT,'Catalog active policy dependency'); END;
CREATE TRIGGER IF NOT EXISTS sd_active_policy_update_guard BEFORE UPDATE ON sd_contract_policies WHEN NEW.state='active' AND ((NEW.calendar_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sd_business_calendars WHERE id=NEW.calendar_id AND country_code=NEW.country_code AND active=1)) OR (NEW.service_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM sd_service_catalog WHERE id=NEW.service_id AND country_code=NEW.country_code AND state='published'))) BEGIN SELECT RAISE(ABORT,'Catalog active policy dependency'); END;
CREATE TRIGGER IF NOT EXISTS sd_calendar_disable_guard BEFORE UPDATE OF active ON sd_business_calendars WHEN NEW.active=0 AND EXISTS(SELECT 1 FROM sd_contract_policies WHERE calendar_id=NEW.id AND state='active') BEGIN SELECT RAISE(ABORT,'Catalog active policy dependency'); END;
CREATE TRIGGER IF NOT EXISTS sd_service_unpublish_guard BEFORE UPDATE OF state ON sd_service_catalog WHEN NEW.state<>'published' AND EXISTS(SELECT 1 FROM sd_contract_policies WHERE service_id=NEW.id AND state='active') BEGIN SELECT RAISE(ABORT,'Catalog active policy dependency'); END;
